<script setup lang="ts">
import {computed,inject,onBeforeUnmount,onMounted,ref} from 'vue';
import {RouterLink} from 'vue-router';
import {adminSessionKey} from './adminSession';
import {promotionDetailGetApiV1AdminPromotionsAgentDirectoryUserId as readDetail,promotionStatusPatchApiV1AdminPromotionsPromotersUserIdStatus as writeStatus,promotionBenefitSettingsGetApiV1AdminPromotionsBenefitSettings as readRates,promotionChangeBenefitSettingsPostApiV1AdminPromotionsBenefitSettings as writeRate,iamListGetApiV1AdminAdmins,ApiError} from './api';
import {money} from './portalAmounts';
import PromoterIcon from './PromoterIcon.vue';
import PromotionLink from './promotion/PromotionLink.vue';
import AgentStatistics from './AgentStatistics.vue';
type Detail=Awaited<ReturnType<typeof readDetail>>['data'];
type Agent=NonNullable<Detail['agent']>;
type Credential=NonNullable<Awaited<ReturnType<typeof iamListGetApiV1AdminAdmins>>['data']>[number];
const props=defineProps<{userId:string;credential?:Credential;credentialsLoaded:boolean;entering:boolean}>();
const emit=defineEmits<{enter:[agent:Agent];createLogin:[payload:{event:Event;agent:Agent}];changed:[]}>();
const session=inject(adminSessionKey),administrator=computed(()=>session?.currentAdmin.value?.role==='ADMIN'),primary=computed(()=>administrator.value&&session?.currentAdmin.value?.primary===true);
const detail=ref<Detail|null>(null),loading=ref(false),error=ref(''),busy=ref(false),copied=ref(false),tab=ref('overview'),editingRate=ref(false),rate=ref(''),reason=ref(''),rateVersion=ref(0),rateLoading=ref(false);
let version=0,alive=true;
const rateAttempt=ref<Parameters<typeof writeRate>[0]>(),statusAttempt=ref<Parameters<typeof writeStatus>[1]>();
const pending=computed(()=>busy.value||!!rateAttempt.value||!!statusAttempt.value);
function retry(){if(rateAttempt.value)void saveRate();else if(statusAttempt.value)void status();else if(editingRate.value)void openRate();else void reload();}
const agent=computed(()=>detail.value?.agent),canEnter=computed(()=>primary.value&&props.credentialsLoaded&&props.credential?.enabled===true&&agent.value?.enabled===true);
const date=(v?:string|null)=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v)).replaceAll('/','-'):'—';
const percent=(v?:string|null)=>v==null?'—':`${Number((Number(v)*100).toFixed(4))}%`;
const source=(v?:string|null)=>({ADMIN:'管理员添加',APPLICATION:'推广申请',UNKNOWN:'未知'}[v||'UNKNOWN']||'未知');
async function reload(){const run=++version;loading.value=true;error.value='';try{const r=await readDetail(props.userId);if(run===version&&alive){if(r.data.agent?.userId!==props.userId)throw Error();detail.value=r.data;}}catch{if(run===version&&alive)error.value='代理详情读取失败，请重试。';}finally{if(run===version&&alive)loading.value=false;}}
async function copyPhone(){if(!agent.value?.phone)return;try{await navigator.clipboard.writeText(agent.value.phone);if(alive)copied.value=true;}catch{if(alive)error.value='复制失败，请重试。';}}
async function openRate(){if(!primary.value||pending.value)return;editingRate.value=true;rateLoading.value=true;error.value='';rateAttempt.value=undefined;reason.value='';try{const r=await readRates();if(!alive)return;rateVersion.value=r.data.version??0;const override=r.data.promoters?.find(p=>p.id===props.userId);rate.value=String(Number(override?.level1CashRate??r.data.global?.defaultLevel1CashRate??'0')*100);}catch{if(alive)error.value='收益比例读取失败，请重试。';}finally{if(alive)rateLoading.value=false;}}
async function saveRate(){if(!primary.value||busy.value||rateLoading.value)return;const n=Number(rate.value);if(!String(rate.value).trim()||!Number.isFinite(n)||n<0||n>100||!reason.value.trim()){error.value='请填写 0–100 的收益比例和调整原因。';return;}busy.value=true;error.value='';rateAttempt.value??={commandId:crypto.randomUUID(),expectedVersion:rateVersion.value,promoterId:props.userId,field:'level1CashRate',rate:(n/100).toFixed(6),reason:reason.value.trim()};try{await writeRate(rateAttempt.value);if(!alive)return;rateAttempt.value=undefined;editingRate.value=false;emit('changed');await reload();}catch(cause){if(!alive)return;if(cause instanceof ApiError&&cause.status>=400&&cause.status<500){rateAttempt.value=undefined;if(cause.status===409){rateVersion.value=0;error.value='收益配置已变化，请重新打开调整后再试。';return;}}error.value='收益比例保存未确认，请重试。';}finally{if(alive)busy.value=false;}}
async function status(){if(!administrator.value||busy.value||!agent.value)return;busy.value=true;error.value='';statusAttempt.value??={commandId:crypto.randomUUID(),status:agent.value.enabled?'DISABLED':'ENABLED',changedAt:new Date().toISOString()};try{await writeStatus(props.userId,statusAttempt.value);if(!alive)return;statusAttempt.value=undefined;emit('changed');await reload();}catch(cause){if(!alive)return;if(cause instanceof ApiError&&cause.status>=400&&cause.status<500)statusAttempt.value=undefined;error.value='代理状态更新未确认，请重试。';}finally{if(alive)busy.value=false;}}
onMounted(reload);onBeforeUnmount(()=>{alive=false;version++;});defineExpose({busy:pending,reload});
</script>
<template>
 <div class="agent-detail-content">
  <p v-if="error" role="alert">{{error}} <button v-if="!busy" @click="retry">重试</button></p><p v-if="loading&&!detail" role="status">正在读取代理详情…</p>
  <template v-if="detail&&agent">
   <section class="agent-detail-profile"><span class="agent-detail-avatar"><svg viewBox="0 0 64 64" fill="currentColor" stroke="#fff" stroke-opacity=".55" stroke-width="1.5" aria-hidden="true"><circle cx="32" cy="18" r="13"/><path d="M9 56v-3c0-12 9-19 23-19s23 7 23 19v3a3 3 0 0 1-3 3H12a3 3 0 0 1-3-3Z"/></svg></span><div class="agent-detail-person"><h3><span>{{agent.nickname||'—'}}</span><span class="pill" :class="agent.enabled?'green':'red'">● {{agent.enabled?'正常':'已停用'}}</span></h3><p class="copy-cell">{{agent.phone?.replace(/^\+86/,'')||'—'}}<button class="icon-button" aria-label="复制代理手机号" @click="copyPhone"><span v-if="copied">✓</span><PromoterIcon v-else name="copy"/></button></p><small>加入时间：{{date(agent.createdAt)}}</small></div><button v-if="primary" class="agent-enter" :disabled="!canEnter||entering||busy" @click="emit('enter',agent)">{{entering?'进入中…':'进入代理后台 ↗'}}</button></section>
   <nav class="agent-detail-tabs" aria-label="代理详情导航"><button v-for="t in [{id:'overview',label:'概览'},{id:'link',label:'推广链接'},{id:'settings',label:'代理设置'}]" :key="t.id" :aria-pressed="tab===t.id" :disabled="pending" @click="tab=t.id;editingRate=false">{{t.label}}</button></nav>
   <template v-if="tab==='overview'">
    <form v-if="editingRate" class="agent-rate-form" aria-label="调整收益比例" @submit.prevent="saveRate"><p v-if="rateLoading" role="status">正在读取收益比例…</p><template v-else><label>收益比例（%）<input v-model="rate" type="number" min="0" max="100" step="0.0001" required :disabled="busy||!!rateAttempt"/></label><label>调整原因<input v-model="reason" required maxlength="2000" :disabled="busy||!!rateAttempt"/></label><footer><button type="button" :disabled="pending" @click="editingRate=false">取消</button><button class="primary-action" :disabled="busy||rateVersion===0">{{busy?'保存中…':'确认调整'}}</button></footer></template></form>
    <section v-else class="agent-core" aria-label="代理核心数据"><header><h3>核心数据</h3><span>累计</span></header><div class="agent-core-row agent-audience-summary"><article><span class="stat-icon green"><svg viewBox="0 0 64 64" fill="currentColor" stroke="#fff" stroke-opacity=".55" stroke-width="1.5" aria-hidden="true"><circle cx="32" cy="18" r="13"/><path d="M9 56v-3c0-12 9-19 23-19s23 7 23 19v3a3 3 0 0 1-3 3H12a3 3 0 0 1-3-3Z"/></svg></span><div><span>推广用户</span><strong>{{agent.invitedCount??'—'}}</strong></div></article><article><span class="stat-icon blue"><svg viewBox="0 0 64 64" fill="currentColor" aria-hidden="true"><path d="M28 48h8v11h-8Z"/><circle cx="32" cy="29" r="24" stroke="#fff" stroke-opacity=".6" stroke-width="2"/><circle cx="32" cy="29" r="17" fill="#d4f0ff" stroke="#fff" stroke-width="2"/><path d="M29 17a13 13 0 0 1 11 21" fill="none" stroke="#6ac8ff" stroke-width="3" stroke-linecap="round"/><path d="M22 27a11 11 0 0 1 4-7" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg></span><div><span>付费用户</span><strong>{{agent.paidCount??'—'}}</strong></div></article></div><div class="agent-core-row three"><article><span class="stat-icon blue"><PromoterIcon name="user"/></span><div><span>个人</span><strong>{{detail.personalPaidCount??'—'}}</strong></div></article><article><span class="stat-icon purple"><PromoterIcon name="bank"/></span><div><span>企业</span><strong>{{detail.enterprisePaidCount??'—'}}</strong></div></article><article><span class="stat-icon gold"><PromoterIcon name="globe"/></span><div><span>API</span><strong>{{detail.apiPaidCount??'—'}}</strong></div></article></div><div class="agent-core-row"><article><div><span>累计充值（元）</span><strong>{{money(agent.totalRechargeAmount4).replace('¥ ','')}}</strong></div></article><article><div><span>累计收益（元）</span><strong>{{money(agent.totalCommissionAmount4).replace('¥ ','')}}</strong></div></article></div><div class="agent-core-row three"><article><div><span>付费率</span><strong>{{detail.paidPercent??'—'}}%</strong></div></article><article><div><span>待结算（元）</span><strong>{{money(agent.pendingCommissionAmount4).replace('¥ ','')}}</strong></div></article><article><div><span>已提现（元）</span><strong>{{money(detail.withdrawnAmount4).replace('¥ ','')}}</strong></div></article></div><div class="agent-rate"><span>当前收益比例</span><strong>{{percent(detail.level1CashRate6)}}</strong><button v-if="primary" @click="openRate">调整</button></div></section>
    <AgentStatistics :user-id="userId" :administrator="administrator" :primary="primary"/>
   </template>
   <section v-else-if="tab==='link'" class="agent-detail-panel"><div class="agent-settings"><h3>推广链接</h3><dl><dt>邀请码</dt><dd>{{agent.invitationCode||'—'}}</dd></dl><PromotionLink :code="agent.invitationCode"/></div></section>
   <section v-else class="agent-detail-panel"><div class="agent-settings"><h3>代理设置</h3><dl><dt>代理来源</dt><dd>{{source(agent.source)}}</dd><dt>代理 ID</dt><dd>{{agent.userId}}</dd><dt>代理状态</dt><dd>{{agent.enabled?'正常':'已停用'}}</dd><template v-if="primary"><dt>登录账号</dt><dd>{{credentialsLoaded?(credential?.username||'未设置'):'读取失败'}}</dd></template><dt>收益比例</dt><dd>{{percent(detail.level1CashRate6)}}</dd></dl><div class="agent-settings-actions"><button v-if="administrator" :disabled="busy" @click="status">{{busy?'更新中…':agent.enabled?'停用代理':'启用代理'}}</button><button v-if="primary&&credentialsLoaded&&!credential&&agent.enabled" :disabled="busy" @click="emit('createLogin',{event:$event,agent})">设置登录账号</button><RouterLink v-else-if="primary&&credential" to="/admin/admins">管理登录账号</RouterLink></div></div></section>
  </template>
 </div>
</template>
